import sys
from itertools import product

def solve():
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    grid = []
    for i in range(n):
        row = data[idx]; idx += 1
        grid.append(row)

    target = "YOKOHAMA"
    count = 0

    directions = [(0,1),(0,-1),(1,0),(-1,0)]


    for i in range(n):
        for j in range(m):
            if grid[i][j] == target[0]:
                stack = [(i, j, 0)]
                while stack:
                    r, c, step = stack.pop()
                    if step == 7:
                        count += 1
                        continue
                    next_char = target[step + 1]
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == next_char:
                            stack.append((nr, nc, step + 1))

    print(count)

solve()
